Layout.Stylesheet:
@font-face { font-family: "Body"; src: local("CrimsonPro-Regular") }
@font-face { font-family: "Body"; font-weight: bold; src: local("CrimsonPro-Bold") }
paragraph.body { font-family: Body, sans-serif; font-size: 12pt }
paragraph.bodybold { font-family: "Body"; font-weight: bold }
paragraph.mono { font-family: Mono }
paragraph.generic { font-family: monospace; font-size: 9pt }
paragraph.unknown { font-family: Unknown, serif }
